mkdeclfn! {
# [doc = " A const reimplementation of the [`transmute`](core::mem::transmute) function,"] # [doc = " avoiding problems when the compiler can't prove equal sizes for some reason."] # [doc = ""] # [doc = " This will still check that the sizes of `A` and `B` are equal at compile time:"] # [doc = " ```compile_fail"] # [doc = " # use generic_array::const_transmute;"] # [doc = ""] # [doc = " let _ = unsafe { const_transmute::<u32, u64>(0u32) }; // panics at compile time"] # [doc = " ```"] # [doc = ""] # [doc = " # Safety"] # [doc = " Treat this the same as [`transmute`](core::mem::transmute), or (preferably) don't use it at all."] # [inline (always)] # [cfg_attr (not (feature = "internals") , doc (hidden))] pub const unsafe fn const_transmute < A , B > (a : A) -> B { struct SizeAsserter < A , B > (PhantomData < (A , B) >) ; impl < A , B > SizeAsserter < A , B > { const ASSERT_SIZE_EQUALITY : () = { if mem :: size_of :: < A > () != mem :: size_of :: < B > () { panic ! ("Size mismatch for generic_array::const_transmute") ; } } ; } let () = SizeAsserter :: < A , B > :: ASSERT_SIZE_EQUALITY ; # [rustversion :: since (1.83)] # [inline (always)] const unsafe fn do_transmute < A , B > (a : A) -> B { mem :: transmute_copy (& ManuallyDrop :: new (a)) } # [rustversion :: before (1.83)] # [inline (always)] const unsafe fn do_transmute < A , B > (a : A) -> B { # [repr (C)] union Union < A , B > { a : ManuallyDrop < A > , b : ManuallyDrop < B > , } let a = ManuallyDrop :: new (a) ; ManuallyDrop :: into_inner (Union { a } . b) } do_transmute (a) }
}